mapper.select:


    deleted_flag = 'N'
     and remark = #{remark}
     and group_code = #{groupCode}
     and group_name like concat('%', #{groupName}, '%')
     and group_type = #{groupType}
    and common_group_id = #{commonGroupId}
     and organization_id = #{organizationId}
     and department_id = #{departmentId}
     and status = #{status}

        and

            (
            userGroup.group_name like concat('%', #{item}, '%')
            or userGroup.remark like concat('%', #{item}, '%')
            )



order by userGroup.created_time desc
